// Shared send-rate limiter for proactive lead messages.
//
// Every worker process on the machine calls reserve() before sending and
// release() if the provider rejects the message. State lives in STATE_DIR so
// it survives restarts and is shared by all workers.
//
// Layout under STATE_DIR:
//   leads/<sha256(userId)>.json  one history file per lead: { retentionMs, sends: [{ id, at }] }
//   locks/<sha256(userId)>.lock  lock directory (mkdir is atomic) held during read-modify-write
//
// What counts as a send: every reservation that was allowed and not released.
// A reservation that is never released (worker crashed mid-send) still counts,
// because the message may have reached the lead.
//
// Limits:
//   per_window_limit  sliding window: fewer than maxPerWindow counted sends in the
//                     last windowHours. A rolling window is what the recipient
//                     experiences: any windowHours span holds at most maxPerWindow.
//   min_gap           no counted send within minGapMinutes of now, on either side.
//
// Failures (bad input, corrupt state, lock timeout) throw. Callers must treat a
// throw as "not sent" and must not send.

import { mkdir, readFile, rename, rm, stat, open } from 'node:fs/promises';
import { createHash, randomUUID } from 'node:crypto';
import path from 'node:path';

const LOCK_WAIT_MS = 10_000;
const STALE_LOCK_MS = 15_000;
const HOUR_MS = 3_600_000;
const MINUTE_MS = 60_000;
const RESERVATION_ID = /^([0-9a-f]{64})\.[0-9a-f-]{36}$/;

export async function reserve(request, now) {
  const { userId, maxPerWindow, windowHours, minGapMinutes } = validateRequest(request);
  const nowMs = validateNow(now);
  const dir = stateDir();
  const key = leadKey(userId);
  const windowMs = windowHours * HOUR_MS;
  const gapMs = minGapMinutes * MINUTE_MS;

  await ensureDirs(dir);
  return withLead(dir, key, async () => {
    const file = leadFile(dir, key);
    const history = await loadHistory(file);
    // Keep records as long as any window or gap seen so far could still need them.
    const retentionMs = Math.max(history.retentionMs ?? 0, windowMs, gapMs);
    const sends = history.sends.filter((s) => s.at >= nowMs - retentionMs);

    const countInWindow = sends.filter((s) => s.at > nowMs - windowMs).length;
    if (countInWindow >= maxPerWindow) {
      return { allowed: false, reason: 'per_window_limit', reservationId: null };
    }
    if (sends.some((s) => Math.abs(nowMs - s.at) < gapMs)) {
      return { allowed: false, reason: 'min_gap', reservationId: null };
    }

    const reservationId = `${key}.${randomUUID()}`;
    sends.push({ id: reservationId, at: nowMs });
    await saveHistory(file, { retentionMs, sends });
    return { allowed: true, reason: null, reservationId };
  });
}

export async function release(reservationId) {
  const match = RESERVATION_ID.exec(typeof reservationId === 'string' ? reservationId : '');
  if (!match) return false;
  const key = match[1];
  const dir = stateDir();
  await ensureDirs(dir);
  return withLead(dir, key, async () => {
    const file = leadFile(dir, key);
    const history = await loadHistory(file);
    const sends = history.sends.filter((s) => s.id !== reservationId);
    if (sends.length === history.sends.length) return false;
    await saveHistory(file, { retentionMs: history.retentionMs, sends });
    return true;
  });
}

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  return dir;
}

function leadKey(userId) {
  return createHash('sha256').update(userId).digest('hex');
}

function leadFile(dir, key) {
  return path.join(dir, 'leads', `${key}.json`);
}

async function ensureDirs(dir) {
  await mkdir(path.join(dir, 'leads'), { recursive: true });
  await mkdir(path.join(dir, 'locks'), { recursive: true });
}

function validateRequest(request) {
  if (request === null || typeof request !== 'object') {
    throw new TypeError('request must be an object');
  }
  const { userId, maxPerWindow, windowHours, minGapMinutes } = request;
  if (typeof userId !== 'string' || userId.length === 0) {
    throw new TypeError('userId must be a non-empty string');
  }
  if (!Number.isInteger(maxPerWindow) || maxPerWindow < 0) {
    throw new TypeError('maxPerWindow must be an integer >= 0');
  }
  if (!Number.isFinite(windowHours) || windowHours <= 0) {
    throw new TypeError('windowHours must be a finite number > 0');
  }
  if (!Number.isFinite(minGapMinutes) || minGapMinutes < 0) {
    throw new TypeError('minGapMinutes must be a finite number >= 0');
  }
  return { userId, maxPerWindow, windowHours, minGapMinutes };
}

function validateNow(now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }
  return now.getTime();
}

// Runs fn while holding the lock for one lead. Other leads are not blocked.
async function withLead(dir, key, fn) {
  const lockDir = path.join(dir, 'locks', `${key}.lock`);
  const deadline = Date.now() + LOCK_WAIT_MS;
  for (;;) {
    try {
      await mkdir(lockDir);
      break;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
      await breakIfStale(lockDir);
      if (Date.now() > deadline) {
        throw new Error(`timed out waiting for lock on lead ${key}`);
      }
      await sleep(5 + Math.random() * 15);
    }
  }
  try {
    return await fn();
  } finally {
    await rm(lockDir, { recursive: true, force: true });
  }
}

// A worker that died while holding the lock leaves the directory behind.
// Rename it aside first so that only one breaker succeeds.
async function breakIfStale(lockDir) {
  let info;
  try {
    info = await stat(lockDir);
  } catch (err) {
    if (err.code === 'ENOENT') return;
    throw err;
  }
  if (Date.now() - info.mtimeMs < STALE_LOCK_MS) return;
  const graveyard = `${lockDir}.stale-${randomUUID()}`;
  try {
    await rename(lockDir, graveyard);
    await rm(graveyard, { recursive: true, force: true });
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
}

async function loadHistory(file) {
  let text;
  try {
    text = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return { retentionMs: 0, sends: [] };
    throw err;
  }
  const history = JSON.parse(text);
  if (!Array.isArray(history.sends)) {
    throw new Error(`corrupt rate-limit state: ${file}`);
  }
  return history;
}

// Write to a temp file, fsync, then rename, so readers never see a partial file.
async function saveHistory(file, history) {
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  const handle = await open(tmp, 'w');
  try {
    await handle.writeFile(JSON.stringify(history));
    await handle.sync();
  } finally {
    await handle.close();
  }
  await rename(tmp, file);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { mkdtemp, utimes, mkdir, writeFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g4-1/bot.mjs';
const root = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = root;
const { reserve, release } = await import(BOT);

const H = 3_600_000;
const M = 60_000;
const t0 = new Date('2026-10-22T10:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);
const req = (o = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0, ...o });

let passed = 0;
const ok = (name) => { passed++; console.log('ok  ', name); };

// 1. per-window cap
{
  const r = [];
  for (let i = 0; i < 4; i++) r.push(await reserve(req({ userId: 'cap' }), at(i * 1000)));
  assert.deepEqual(r.slice(0, 3).map((x) => x.allowed), [true, true, true]);
  assert.equal(r[3].allowed, false);
  assert.equal(r[3].reason, 'per_window_limit');
  assert.equal(r[3].reservationId, null);
  ok('per_window_limit after maxPerWindow sends');
}

// 2. min gap, both sides, exact boundary allowed
{
  const q = req({ userId: 'gap', maxPerWindow: 10, minGapMinutes: 90 });
  assert.equal((await reserve(q, at(0))).allowed, true);
  const a = await reserve(q, at(30 * M));
  assert.equal(a.reason, 'min_gap');
  assert.equal((await reserve(q, at(90 * M))).allowed, true);
  ok('min_gap blocks within gap, allows at exactly gap');
}

// 3. min gap also looks backward (a send recorded later than now)
{
  const q = req({ userId: 'gapback', maxPerWindow: 10, minGapMinutes: 90 });
  assert.equal((await reserve(q, at(120 * M))).allowed, true);
  assert.equal((await reserve(q, at(60 * M))).reason, 'min_gap');
  ok('min_gap is symmetric around now');
}

// 4. sliding window, not fixed buckets
{
  const q = req({ userId: 'slide', maxPerWindow: 2, windowHours: 24, minGapMinutes: 0 });
  assert.equal((await reserve(q, at(0))).allowed, true);
  assert.equal((await reserve(q, at(10 * H))).allowed, true);
  assert.equal((await reserve(q, at(20 * H))).reason, 'per_window_limit');
  // at t0+24h the first send has left the window, so one slot is free again
  assert.equal((await reserve(q, at(24 * H))).allowed, true);
  // t0+10h is still inside (t0+24h-24h... window now (t0, t0+24h]); count is 2 -> blocked
  assert.equal((await reserve(q, at(24 * H + 1000))).reason, 'per_window_limit');
  ok('sliding window frees a slot exactly when the oldest send ages out');
}

// 5. per-call limits may differ for the same lead
{
  const strict = req({ userId: 'vary', maxPerWindow: 1 });
  const loose = req({ userId: 'vary', maxPerWindow: 5 });
  assert.equal((await reserve(strict, at(0))).allowed, true);
  assert.equal((await reserve(strict, at(1000))).reason, 'per_window_limit');
  assert.equal((await reserve(loose, at(2000))).allowed, true);
  ok('limits come from each call');
}

// 6. release frees the slot; second release and unknown ids are no-ops
{
  const q = req({ userId: 'rel', maxPerWindow: 1 });
  const first = await reserve(q, at(0));
  assert.equal((await reserve(q, at(1000))).reason, 'per_window_limit');
  assert.equal(await release(first.reservationId), true);
  assert.equal(await release(first.reservationId), false);
  assert.equal(await release('not-an-id'), false);
  assert.equal(await release(null), false);
  assert.equal((await reserve(q, at(2000))).allowed, true);
  ok('release returns the slot once; bad ids are ignored');
}

// 7. a released reservation does not count toward min_gap either
{
  const q = req({ userId: 'relgap', maxPerWindow: 10, minGapMinutes: 90 });
  const a = await reserve(q, at(0));
  await release(a.reservationId);
  assert.equal((await reserve(q, at(5 * M))).allowed, true);
  ok('released send does not block min_gap');
}

// 8. input validation throws (fail closed)
{
  await assert.rejects(reserve(req({ maxPerWindow: -1 }), at(0)), TypeError);
  await assert.rejects(reserve(req({ windowHours: 0 }), at(0)), TypeError);
  await assert.rejects(reserve(req({ userId: '' }), at(0)), TypeError);
  await assert.rejects(reserve(req(), 12345), TypeError);
  await assert.rejects(reserve(req(), new Date('nope')), TypeError);
  ok('invalid input throws');
}

// 9. stale lock left by a dead worker is broken
{
  const q = req({ userId: 'stale' });
  const key = (await import('node:crypto')).createHash('sha256').update('stale').digest('hex');
  await mkdir(path.join(root, 'locks'), { recursive: true });
  const lock = path.join(root, 'locks', `${key}.lock`);
  await mkdir(lock);
  const old = new Date(Date.now() - 3600_000);
  await utimes(lock, old, old);
  const r = await reserve(q, at(0));
  assert.equal(r.allowed, true);
  ok('stale lock is broken');
}

// 10. multi-process: 12 workers race on one lead at the same instant
function runChild(code, env = {}) {
  return new Promise((resolve, reject) => {
    const p = spawn(process.execPath, ['--input-type=module', '-e', code], {
      env: { ...process.env, STATE_DIR: root, ...env },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let out = '';
    let err = '';
    p.stdout.on('data', (d) => (out += d));
    p.stderr.on('data', (d) => (err += d));
    p.on('close', (code) => (code === 0 ? resolve(out.trim()) : reject(new Error(err || `exit ${code}`))));
  });
}

{
  const code = `
    const { reserve } = await import(${JSON.stringify(BOT)});
    const r = await reserve({ userId: 'race', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 }, new Date(${t0.getTime()}));
    console.log(JSON.stringify(r));`;
  const outs = await Promise.all(Array.from({ length: 12 }, () => runChild(code)));
  const res = outs.map((o) => JSON.parse(o));
  assert.equal(res.filter((r) => r.allowed).length, 3);
  assert.equal(res.filter((r) => r.reason === 'per_window_limit').length, 9);
  ok('12 concurrent processes: exactly 3 allowed');

  // 11. state survives: a new process sees the 3 sends
  const check = await runChild(`
    const { reserve } = await import(${JSON.stringify(BOT)});
    console.log(JSON.stringify(await reserve({ userId: 'race', maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 }, new Date(${t0.getTime() + 1000}))));`);
  assert.equal(JSON.parse(check).reason, 'per_window_limit');
  ok('history survives process restart and is seen by new worker');

  // 12. another process releases a slot reserved by the first one
  const allowedId = res.find((r) => r.allowed).reservationId;
  const rel = await runChild(`
    const { release } = await import(${JSON.stringify(BOT)});
    console.log(JSON.stringify(await release(${JSON.stringify(allowedId)})));`);
  assert.equal(JSON.parse(rel), true);
  const again = await reserve(req({ userId: 'race' }), new Date(t0.getTime() + 2000));
  assert.equal(again.allowed, true);
  ok('reservation released from a different process frees the slot');
}

// 13. multi-process with different leads does not serialize incorrectly; many leads, same time
{
  const code = `
    const { reserve } = await import(${JSON.stringify(BOT)});
    const r = await reserve({ userId: 'lead_' + process.argv[1], maxPerWindow: 1, windowHours: 24, minGapMinutes: 0 }, new Date(${t0.getTime()}));
    console.log(JSON.stringify(r));`;
  const outs = await Promise.all(Array.from({ length: 12 }, (_, i) =>
    runChild(code.replace('process.argv[1]', String(i)))));
  assert.ok(outs.every((o) => JSON.parse(o).allowed));
  ok('12 different leads in parallel all allowed');
}

// 14. corrupt state fails closed
{
  const key = (await import('node:crypto')).createHash('sha256').update('corrupt').digest('hex');
  await writeFile(path.join(root, 'leads', `${key}.json`), '{not json');
  await assert.rejects(reserve(req({ userId: 'corrupt' }), at(0)));
  ok('corrupt state throws instead of allowing');
}

// Leftover lock dirs should be gone after everything
const locks = await readdir(path.join(root, 'locks'));
assert.deepEqual(locks.filter((n) => n.endsWith('.lock')), []);
ok('no lock directories left behind');

console.log(`\n${passed} checks passed (state dir ${root})`);
